import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class MiniJUnit {
    @Retention(RetentionPolicy.RUNTIME) @interface Test {}
    @Retention(RetentionPolicy.RUNTIME) @interface BeforeEach {}
    @Retention(RetentionPolicy.RUNTIME) @interface AfterEach {}

    static class Counter {
        int value;
        void inc() { value++; }
    }

    public static class CounterTests {
        private Counter counter;

        @BeforeEach void setUp()    { counter = new Counter(); System.out.println("  setUp"); }
        @AfterEach  void tearDown() { System.out.println("  tearDown"); }

        @Test void startsAtZero() { check(counter.value == 0, "expected 0"); }
        @Test void incrementsOnce() { counter.inc(); check(counter.value == 1, "expected 1"); }
        @Test void deliberatelyFailing() { counter.inc(); check(counter.value == 2, "expected 2"); }

        static void check(boolean ok, String msg) { if (!ok) throw new AssertionError(msg); }
    }

    public static void main(String[] args) throws Exception {
        Class<?> type = CounterTests.class;
        int passed = 0, failed = 0;
        for (Method m : type.getDeclaredMethods()) {
            if (!m.isAnnotationPresent(Test.class)) continue;
            Object instance =
                    type.getDeclaredConstructor().newInstance();   // new instance per test
            System.out.println(m.getName());
            run(instance, BeforeEach.class);
            try {
                m.invoke(instance);
                passed++;
                System.out.println("  PASS");
            } catch (InvocationTargetException e) {
                failed++;
                System.out.println("  FAIL: " + e.getCause().getMessage());
            } finally {
                run(instance, AfterEach.class);
            }
        }
        System.out.println(passed + " passed, " + failed + " failed");
    }

    static void run(Object o, Class<? extends Annotation> a) throws Exception {
        for (Method m : o.getClass().getDeclaredMethods())
            if (m.isAnnotationPresent(a)) { m.setAccessible(true); m.invoke(o); }
    }
}

import java.lang.reflect.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;

public class MiniMock {
    interface PaymentGateway { boolean charge(String account, BigDecimal amount); }

    /** Unit under test: applies a 10% promotion until the promotion deadline. */
    static class CheckoutService {
        private final PaymentGateway gateway;
        private final Clock clock;
        private final Instant promoEnds;
        CheckoutService(PaymentGateway gateway, Clock clock, Instant promoEnds) {
            this.gateway = gateway; this.clock = clock; this.promoEnds = promoEnds;
        }
        boolean checkout(String account, BigDecimal price) {
            BigDecimal due = clock.instant().isBefore(promoEnds)
                    ? price.multiply(new BigDecimal("0.90")) : price;
            return gateway.charge(account, due);
        }
    }

    /** A tiny Mockito-like recorder built on java.lang.reflect.Proxy. */
    static class Mock implements InvocationHandler {
        final List<String> calls = new ArrayList<>();
        final List<Object[]> argsSeen = new ArrayList<>();
        Object answer = false;
        @Override public Object invoke(Object proxy, Method m, Object[] args) {
            calls.add(m.getName());
            argsSeen.add(args);
            return answer;
        }
    }

    public static void main(String[] args) {
        Instant ends = Instant.parse("2026-12-31T23:59:59Z");

        Mock handler = new Mock();
        handler.answer = true;
        ClassLoader loader = PaymentGateway.class.getClassLoader();
        PaymentGateway gateway = (PaymentGateway) Proxy.newProxyInstance(
                loader, new Class<?>[]{PaymentGateway.class}, handler);

        Clock before = Clock.fixed(Instant.parse("2026-12-01T10:00:00Z"), ZoneOffset.UTC);
        Clock after  = Clock.fixed(Instant.parse("2027-01-01T00:00:00Z"), ZoneOffset.UTC);

        new CheckoutService(gateway, before, ends).checkout("acc-1", new BigDecimal("200.00"));
        new CheckoutService(gateway, after,  ends).checkout("acc-1", new BigDecimal("200.00"));

        System.out.println("calls     = " + handler.calls);
        System.out.println("captured  = " + handler.argsSeen.get(0)[1]
                + " , " + handler.argsSeen.get(1)[1]);
        System.out.println("verify times(2) -> " + (handler.calls.size() == 2));
    }
}

