import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class PricingServiceTest {

    private static final Instant NOW = Instant.parse("2026-06-01T12:00:00Z");

    @Mock CouponRepository coupons;
    PricingService service;

    @org.junit.jupiter.api.BeforeEach
    void setUp() {
        service = new PricingService(coupons, Clock.fixed(NOW, ZoneOffset.UTC));
    }

    @Test
    @DisplayName("without a coupon the subtotal is returned unchanged")
    void noCoupon() {
        assertThat(service.total(new BigDecimal("50.00"), null)).isEqualByComparingTo("50.00");
    }

    @Nested
    class WithCoupon {

        @ParameterizedTest(name = "{0}% of {1} leaves {2}")
        @CsvSource({"10, 200.00, 180.00", "25, 80.00, 60.00", "33, 10.00, 6.70"})
        void appliesPercentage(String percent, String subtotal, String expected) {
            given(coupons.findByCode("SAVE"))
                    .willReturn(Optional.of(new Coupon("SAVE", new BigDecimal(percent),
                            NOW.plusSeconds(60))));

            assertThat(service.total(new BigDecimal(subtotal), "SAVE"))
                    .isEqualByComparingTo(expected);
        }

        @Test
        void expiredCouponIsRejected() {
            given(coupons.findByCode("OLD"))
                    .willReturn(Optional.of(
                            new Coupon("OLD", BigDecimal.TEN, NOW.minusSeconds(1))));

            assertThatThrownBy(() -> service.total(new BigDecimal("10.00"), "OLD"))
                    .isInstanceOf(ExpiredCouponException.class)
                    .hasMessageContaining("OLD");
        }

        @Test
        void unknownCouponIsRejected() {
            given(coupons.findByCode("NOPE")).willReturn(Optional.empty());

            assertThatThrownBy(() -> service.total(new BigDecimal("10.00"), "NOPE"))
                    .isInstanceOf(UnknownCouponException.class);
        }
    }
}

import java.util.*;
import java.util.concurrent.*;

public class FlakyDemo {
    static final List<String> SHARED = new ArrayList<>();          // static state shared by "tests"

    static boolean testAddsOne() {
        SHARED.clear();
        SHARED.add("a");
        pause();
        return SHARED.size() == 1;
    }
    static boolean testAddsTwo() {
        SHARED.clear();
        SHARED.add("a"); SHARED.add("b");
        pause();
        return SHARED.size() == 2;
    }
    static void pause() { Thread.onSpinWait(); }

    public static void main(String[] args) throws Exception {
        int runs = 200, sequentialFailures = 0, parallelFailures = 0;
        ExecutorService pool = Executors.newFixedThreadPool(2);
        for (int i = 0; i < runs; i++) {
            if (!testAddsOne() || !testAddsTwo()) sequentialFailures++;
            Future<Boolean> f1 = pool.submit(FlakyDemo::testAddsOne);
            Future<Boolean> f2 = pool.submit(FlakyDemo::testAddsTwo);
            if (!(f1.get() && f2.get())) parallelFailures++;
        }
        pool.shutdown();
        System.out.println("sequential: " + sequentialFailures + " failing suites out of " + runs);
        System.out.println("parallel  : " + parallelFailures + " failing suites out of " + runs);
    }
}

