import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.context.annotation.Import;
import org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import shop.config.SecurityConfig;

@WebMvcTest(AdminController.class)
@Import(SecurityConfig.class)
class AdminEndpointSecurityTest {

    @Autowired MockMvc mvc;
    @MockitoBean AdminService admin;
    @MockitoBean org.springframework.security.oauth2.jwt.JwtDecoder jwtDecoder;

    @Test
    void anonymousIsUnauthorized() throws Exception {
        mvc.perform(delete("/admin/users/5")).andExpect(status().isUnauthorized());
    }
    @Test
    void userWithoutAuthorityIsForbidden() throws Exception {
        mvc.perform(delete("/admin/users/5")
                .with(SecurityMockMvcRequestPostProcessors.jwt()
                        .authorities(() -> "SCOPE_orders:read")))
            .andExpect(status().isForbidden());
    }

    @Test
    void adminSucceeds() throws Exception {
        mvc.perform(delete("/admin/users/5")
                .with(SecurityMockMvcRequestPostProcessors.jwt()
                        .authorities(() -> "ROLE_ADMIN")))
            .andExpect(status().isNoContent());
    }
}

